/**
 * Rule-table and parcel types for the max-buildable engine and the ordinance reader.
 *
 * Every zoning value is a SourcedNumber: it carries its status and, when read, its
 * citation (ordinance, effective date, section, page, and exact quoted source text).
 * A value that cannot be read is "not-found" or "needs-reading" and is NEVER replaced
 * by an estimate — it blocks any calculation that depends on it (handoff: ordinance
 * source reader rules). No value in this module is ever generated by a model.
 */

export type ValueStatus =
  | "parsed" // read from the ordinance and passed the quote check
  | "person-entered" // a reviewer typed it after reading the page image
  | "corrected" // a reviewer corrected a parsed value
  | "computed" // derived by a visible formula from stated inputs
  | "not-regulated" // the district does not regulate this standard (legitimately absent)
  | "not-found" // present in the ordinance but could not be read
  | "needs-reading"; // the parser could not match it with certainty

export interface Citation {
  ordinance: string;
  effectiveDate: string;
  section: string;
  page: string;
  /** The exact source line the value came from (the quote check runs against this). */
  quote: string;
  verifier?: string;
  verifiedOn?: string;
}

export interface SourcedNumber {
  status: ValueStatus;
  value?: number; // present for parsed / person-entered / corrected / computed
  citation?: Citation;
  /** For computed values: the visible formula, shown beside the ordinance's wording. */
  formula?: string;
  note?: string;
}

export interface DimensionalStandards {
  minLotSf?: SourcedNumber;
  setbacksFt?: { front?: SourcedNumber; side?: SourcedNumber; rear?: SourcedNumber };
  maxHeightFt?: SourcedNumber;
  maxStories?: SourcedNumber;
  maxFar?: SourcedNumber;
  maxLotCoverage?: SourcedNumber; // fraction 0..1
  maxDensityDuAc?: SourcedNumber;
  parking?: { perUnit?: SourcedNumber; stallSf?: SourcedNumber };
  minOpenSpacePct?: SourcedNumber; // fraction 0..1
}

/** An optional density/height bonus (affordability, transit, …) with its trigger. */
export interface BonusProvision {
  label: string;
  trigger: string;
  citation?: Citation;
  /** The standards it overrides when triggered. */
  effect: Partial<DimensionalStandards>;
}

/** A prose condition shown verbatim with its citation, never turned into a number. */
export interface ProseNote {
  text: string;
  citation?: Citation;
}

export interface District {
  name: string;
  permittedUses: string[];
  byRight: DimensionalStandards;
  /** Maxima the ordinance itself states for special exception / site plan / planned district. */
  planBased?: DimensionalStandards;
  bonuses?: BonusProvision[];
  notes?: ProseNote[];
}

export interface RuleTable {
  jurisdiction: string;
  verified: boolean;
  verifiedOn?: string;
  districts: Record<string, District>;
}

/**
 * A parcel. For golden tests a rectangle (width × depth) makes setback insets and area
 * hand-verifiable; from GIS, `areaSf` (and optionally `widthFt`/`depthFt`) come from the
 * parcel layer. `excludedAreaSf` is area removed by constraint layers (floodway, wash,
 * steep slope).
 */
export interface Parcel {
  areaSf: number;
  widthFt?: number;
  depthFt?: number;
  excludedAreaSf?: number;
}

/** Design inputs (not zoning): efficiency, average unit size, floor-to-floor height. */
export interface BuildableProgram {
  efficiency: number; // net / gross (0..1)
  avgUnitNetSf: number;
  floorToFloorFt: number; // used only to convert a height limit to stories when stories is absent
}

export interface BuildableOptions {
  case: "by-right" | "plan-based";
  parkingType?: "surface" | "structured"; // default "surface"
  /** A user-entered density (plan-based), labeled as not from the ordinance. */
  userDensityDuAc?: number;
}
